var row = msg.payload && msg.payload[0];
if (!row) {
    return null;
}
var base = "team13-1/icetruck/";
var msgs = [
    { topic: base + "sensors/sensor_board_raw", payload: row.sensor_board_raw, retain: true },
    { topic: base + "sensors/sensor_board_temp_c", payload: row.sensor_board_temp_c, retain: true },
    { topic: base + "sensors/actor_board_raw", payload: row.actor_board_raw, retain: true },
    { topic: base + "sensors/actor_board_temp_c", payload: row.actor_board_temp_c, retain: true },
    { topic: base + "actuators/fan_pwm", payload: row.fan_pwm, retain: true },
    { topic: base + "actuators/valve_angle", payload: row.valve_angle, retain: true },
    { topic: base + "status", payload: JSON.stringify(row), retain: true }
];
return [msgs];

var parts = msg.topic.split("/");
var field = parts[3]; // "mode" | "fan_pwm" | "valve_angle"
var value = msg.payload;

if (field === "mode") {
    if (value !== "auto" && value !== "manual") {
        node.warn("Ungueltiger mode: " + value);
        return null;
    }
} else if (field === "fan_pwm") {
    value = Math.max(0, Math.min(255, parseInt(value, 10)));
} else if (field === "valve_angle") {
    value = Math.max(0, Math.min(180, parseInt(value, 10)));
} else {
    node.warn("Unbekanntes control-Topic: " + msg.topic);
    return null;
}

// TODO: Issue #180 ist erledigt, hardware.py:write_actor_setpoints() schreibt
// bereits echt per I2C - hier fehlt nur noch der Schritt, der diese
// validierten Befehle tatsaechlich an write_actor_setpoints() weiterreicht
// (z.B. per Exec-Node/kleinem HTTP-Endpoint auf dem Pi-Backend).
var record = { field: field, value: value, received_at: new Date().toISOString() };
return [{ payload: record }, { payload: JSON.stringify(record) }];
